(function () { 'use strict'; const header = document.getElementById('header'); if (header) { window.addEventListener('scroll', () => { header.classList.toggle('header--scrolled', window.scrollY > 10); }, { passive: true }); } const burger = document.querySelector('.burger'); const mobileMenu = document.getElementById('mobile-menu'); if (burger && mobileMenu) { burger.addEventListener('click', () => { const expanded = burger.getAttribute('aria-expanded') === 'true'; burger.setAttribute('aria-expanded', !expanded); mobileMenu.hidden = expanded; }); mobileMenu.querySelectorAll('a').forEach(link => { link.addEventListener('click', () => { burger.setAttribute('aria-expanded', 'false'); mobileMenu.hidden = true; }); }); } function formatPhone(value) { const digits = value.replace(/\D/g, ''); let formatted = '+375 '; if (digits.length > 3) { const code = digits.slice(3, 5); formatted += '(' + code; if (digits.length > 5) { formatted += ') ' + digits.slice(5, 8); if (digits.length > 8) { formatted += '-' + digits.slice(8, 10); if (digits.length > 10) { formatted += '-' + digits.slice(10, 12); } } } } return formatted.trim(); } document.querySelectorAll('input[type="tel"]').forEach(input => { input.addEventListener('input', () => { input.value = formatPhone(input.value); input.setSelectionRange(input.value.length, input.value.length); }); }); const toast = document.getElementById('toast'); function showToast() { if (!toast) return; toast.hidden = false; setTimeout(() => { toast.hidden = true; }, 4000); } const feedbackForm = document.getElementById('feedback-form'); feedbackForm?.addEventListener('submit', (e) => { e.preventDefault(); const phone = feedbackForm.querySelector('[name="phone"]')?.value || ''; if (phone.replace(/\D/g, '').length < 12) { alert('Пожалуйста, введите корректный номер телефона'); return; } if (typeof gtag === 'function') { gtag('event', 'generate_lead', { event_category: 'form', event_label: 'feedback-form' }); } if (typeof ym === 'function') { ym(, 'reachGoal', 'lead_form'); } feedbackForm.reset(); showToast(); }); const mastersEl = document.getElementById('masters-count'); if (mastersEl) { setInterval(() => { const delta = Math.random() > 0.5 ? 1 : -1; const current = parseInt(mastersEl.textContent, 10); const next = Math.max(2, Math.min(5, current + delta)); mastersEl.textContent = next; }, 8000); } function trackEvent(name) { if (typeof gtag === 'function') gtag('event', name, { event_category: 'conversion' }); if (typeof ym === 'function') ym(, 'reachGoal', name); } document.querySelectorAll('a[href^="tel:"]').forEach(link => { link.addEventListener('click', () => trackEvent('phone_call')); }); document.querySelectorAll('[data-social]').forEach(link => { link.addEventListener('click', () => trackEvent('social_' + link.dataset.social)); }); document.querySelectorAll('a[href^="#"]').forEach(anchor => { anchor.addEventListener('click', (e) => { const target = document.querySelector(anchor.getAttribute('href')); if (target) { e.preventDefault(); target.scrollIntoView({ behavior: 'smooth' }); } }); }); })();